// Installed Elementor public markup -> native export -> browser interactions.
import assert from 'node:assert/strict';import{mkdtemp,rm,readFile,writeFile}from'node:fs/promises';import{tmpdir}from'node:os';import path from'node:path';import{chromium}from'playwright';
import{parseContent,YAML}from'../../scripts/source-project.mjs';import{extract}from'../../engine/extract.mjs';import{generate}from'../../engine/generate.mjs';import{run}from'../../engine/pipeline.mjs';import{serveStatic}from'../../engine/static.mjs';
const origin='http://127.0.0.1:9426',routes=['/components/','/vertical-components/'],dir=await mkdtemp(path.join(tmpdir(),'installed-widgets-'));let browser,server;const checks=[];
try{
 const pages=[];for(const route of routes){const response=await fetch(origin+route);assert.equal(response.status,200);const html=await response.text();for(const type of ['tabs','accordion','toggle'])assert.ok(html.includes('data-widget_type="'+type+'.default"'),'actual installed '+type+' markup');pages.push({...extract(html,origin+route),styles:[]});}
 await generate({source:origin+'/',identity:{title:'Component Studio'},design:{},navigation:[],metrics:{},pages,media:[]},dir);await run(process.execPath,['scripts/build.mjs'],{cwd:dir,timeout:120000});const records=JSON.parse(await readFile(path.join(dir,'routes.json'),'utf8')),record=records.find(r=>r.route==='/components/'),file=path.join(dir,'content',record.collection,record.slug+'.md'),parsed=parseContent(await readFile(file,'utf8'),file);assert.ok(parsed.body.includes('tabs Design content.'),'hidden panel prose is editable Markdown');await writeFile(file,'---\n'+YAML.stringify(parsed.meta)+'---\n'+parsed.body.replace('tabs Design content.','Edited design panel.'));await run(process.execPath,['scripts/build.mjs'],{cwd:dir,timeout:120000});
 server=await serveStatic(path.join(dir,'output'));browser=await chromium.launch({channel:'chrome'});
 for(const route of routes)for(const width of[1440,390])for(const[side,base]of[['source',origin],['export',server.url]]){
  const page=await browser.newPage({viewport:{width,height:1000}});await page.route('**/*',r=>['GET','HEAD'].includes(r.request().method())&&new URL(r.request().url()).origin===new URL(base).origin?r.continue():r.abort());await page.goto(base+route,{waitUntil:'networkidle'});
  assert.equal(await page.locator('[data-widget_type="accordion.default"] .elementor-tab-content').first().isVisible(),true,'classic accordion initially expands its first panel');assert.equal(await page.locator('[data-widget_type="toggle.default"] .elementor-tab-content').first().isVisible(),false,'toggle initially stays collapsed');
  const tabs=page.locator('[data-widget_type="tabs.default"]'),titles=tabs.locator(width===390?'.elementor-tab-mobile-title':'.elementor-tab-desktop-title'),panels=tabs.locator('.elementor-tab-content');await titles.nth(1).click();await page.waitForFunction(()=>document.querySelector('[data-widget_type="tabs.default"] .elementor-tab-content[data-tab="2"]')?.getBoundingClientRect().height>0);assert.equal(await panels.nth(0).isVisible(),false);assert.equal(await panels.nth(1).isVisible(),true);if(side==='export'&&route==='/components/')assert.ok((await panels.nth(1).innerText()).includes('Edited design panel.'));else assert.ok((await panels.nth(1).innerText()).includes('tabs Design content.'));
  const accordion=page.locator('[data-widget_type="accordion.default"]');await accordion.locator('.elementor-tab-title').nth(1).click();await page.waitForTimeout(400);assert.equal(await accordion.locator('.elementor-tab-content').nth(1).isVisible(),true);assert.equal(await accordion.locator('.elementor-tab-content').nth(0).isVisible(),false);
  const toggle=page.locator('[data-widget_type="toggle.default"]');await toggle.locator('.elementor-tab-title').nth(0).click();await toggle.locator('.elementor-tab-title').nth(1).click();await page.waitForTimeout(400);assert.equal(await toggle.locator('.elementor-tab-content').nth(0).isVisible(),true);assert.equal(await toggle.locator('.elementor-tab-content').nth(1).isVisible(),true);
  checks.push({route,width,side,tabs:true,exclusiveAccordion:true,independentToggle:true});await page.close();
 }
 console.log(JSON.stringify({plugin:'elementor',version:'4.3.5',checks,hiddenPanelMarkdownEdit:true,aiCalls:0,scope:'Installed classic widgets and native export interactions; styling, nested widgets, motion, Pro and held-out configurations not established'}));
}finally{await browser?.close();await server?.close();await rm(dir,{recursive:true,force:true});}
